// 变成另一件事，要改归属只能删了重登，理由同 upstream_account 不许改
// environment。
func (q *Queries) UpdateServerServiceNote(ctx context.Context, arg UpdateServerServiceNoteParams) (CoreServerServiceNote, error) {
	row := q.db.QueryRow(ctx, updateServerServiceNote,
		arg.ServiceName,
		arg.ServiceKind,
		arg.Port,
		arg.Notes,
		arg.ID,
	)
	var i CoreServerServiceNote
	err := row.Scan(
		&i.ID,
		&i.ServerID,
		&i.ServiceName,
		&i.ServiceKind,
		&i.Port,
		&i.Notes,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}

const updateServerSupplier = `-- name: UpdateServerSupplier :one
UPDATE core.server_supplier SET
    name         = $1,
    website      = $2,
    console_url  = $3,
    contact_name = $4,
    contact_info = $5,
    notes        = $6,
    updated_at   = now()
WHERE id = $7
RETURNING id, name, website, console_url, contact_name, contact_info, notes, environment, created_at, updated_at
`

type UpdateServerSupplierParams struct {
	Name        string
	Website     *string
	ConsoleUrl  *string
	ContactName *string
	ContactInfo *string
	Notes       *string
	ID          uuid.UUID
}

// 不含 environment：身份边界，改它等于把一条生产供应商搬进 staging（宪法 15 条）。
func (q *Queries) UpdateServerSupplier(ctx context.Context, arg UpdateServerSupplierParams) (CoreServerSupplier, error) {
	row := q.db.QueryRow(ctx, updateServerSupplier,
		arg.Name,
		arg.Website,
		arg.ConsoleUrl,
		arg.ContactName,
		arg.ContactInfo,
		arg.Notes,
		arg.ID,
	)
	var i CoreServerSupplier
	err := row.Scan(
		&i.ID,
		&i.Name,
		&i.Website,
		&i.ConsoleUrl,
		&i.ContactName,
		&i.ContactInfo,
		&i.Notes,
		&i.Environment,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}
